//! Data access for `PUT /notes/{id}` and `DELETE /notes/{id}`.
//!
//! Updates reuse [`super::notes::replace_tags`]; deleting a note removes its tags through
//! `ON DELETE CASCADE`.

use rusqlite::{Connection, TransactionBehavior, params};

use super::notes::replace_tags;
use crate::model::{Note, NoteInput};

/// Replaces the content of the note with this id. Returns `None` if it does not exist.
pub fn update(conn: &mut Connection, id: i64, input: NoteInput) -> rusqlite::Result<Option<Note>> {
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let changed = tx
        .prepare_cached("UPDATE notes SET title = ?1, body = ?2 WHERE id = ?3")?
        .execute(params![input.title, input.body, id])?;
    if changed == 0 {
        return Ok(None);
    }
    replace_tags(&tx, id, &input.tags)?;
    tx.commit()?;
    let NoteInput { title, body, tags } = input;
    Ok(Some(Note {
        id,
        title,
        body,
        tags,
    }))
}

/// Deletes the note with this id and its tags. Returns whether it existed.
pub fn delete(conn: &Connection, id: i64) -> rusqlite::Result<bool> {
    let deleted = conn
        .prepare_cached("DELETE FROM notes WHERE id = ?1")?
        .execute([id])?;
    Ok(deleted > 0)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db::notes::{get, insert, tags_of};
    use crate::db::test_util::{conn, temp_db};

    fn input(title: &str, body: &str, tags: &[&str]) -> NoteInput {
        NoteInput {
            title: title.into(),
            body: body.into(),
            tags: tags.iter().map(|&t| t.to_owned()).collect(),
        }
    }

    #[test]
    fn update_replaces_content_and_tags() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        let note = insert(&mut conn, input("old", "text", &["x", "y"])).unwrap();
        let updated = update(&mut conn, note.id, input("new", "", &["a", "y"]))
            .unwrap()
            .expect("note exists");
        assert_eq!(
            updated,
            Note {
                id: note.id,
                title: "new".into(),
                body: String::new(),
                tags: vec!["a".into(), "y".into()],
            }
        );
        assert_eq!(get(&conn, note.id).unwrap(), Some(updated));
    }

    #[test]
    fn update_missing_note() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        assert_eq!(update(&mut conn, 1, input("t", "", &["a"])).unwrap(), None);
        assert_eq!(
            tags_of(&conn, 1).unwrap(),
            Vec::<String>::new(),
            "no orphan tags"
        );
    }

    #[test]
    fn delete_removes_note_and_tags() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        let note = insert(&mut conn, input("a", "", &["x"])).unwrap();
        assert!(delete(&conn, note.id).unwrap());
        assert_eq!(get(&conn, note.id).unwrap(), None);
        assert_eq!(tags_of(&conn, note.id).unwrap(), Vec::<String>::new());
        assert!(!delete(&conn, note.id).unwrap());
    }
}

//! Data access for `GET /notes` and its filters.
//!
//! Tags live in the `note_tags` table (indexed by tag); see [`super::notes::tags_of`].

use rusqlite::{Connection, params};

use crate::model::Note;

/// Which notes `GET /notes` returns. Every filter is optional; they combine with AND.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ListFilter {
    /// Only notes that have this tag.
    pub tag: Option<String>,
    /// Only notes whose title or body contains this text, ignoring ASCII case.
    pub text: Option<String>,
    /// Only notes with an id greater than this.
    pub after: Option<i64>,
    /// At most this many notes.
    pub limit: u32,
}

impl Default for ListFilter {
    fn default() -> Self {
        Self {
            tag: None,
            text: None,
            after: None,
            limit: 100,
        }
    }
}

/// The notes matching `filter`, ordered by id ascending.
///
/// A single statement reads notes and their tags, so the result is a consistent snapshot even
/// while other requests write.
pub fn list(conn: &Connection, filter: &ListFilter) -> rusqlite::Result<Vec<Note>> {
    // SQLite's `lower()` folds ASCII letters only (no ICU in the bundled build), which is exactly
    // the case-insensitivity the API promises. `instr` avoids LIKE's `%` and `_` wildcards.
    let mut statement = conn.prepare_cached(
        "SELECT n.id, n.title, n.body, t.tag
         FROM (
             SELECT id, title, body FROM notes
             WHERE (?1 IS NULL OR id > ?1)
               AND (?2 IS NULL OR id IN (SELECT note_id FROM note_tags WHERE tag = ?2))
               AND (?3 IS NULL OR instr(lower(title), ?3) > 0 OR instr(lower(body), ?3) > 0)
             ORDER BY id
             LIMIT ?4
         ) AS n
         LEFT JOIN note_tags AS t ON t.note_id = n.id
         ORDER BY n.id, t.tag",
    )?;
    let needle = filter.text.as_deref().map(str::to_ascii_lowercase);
    let mut rows = statement.query(params![filter.after, filter.tag, needle, filter.limit])?;

    let mut notes: Vec<Note> = Vec::new();
    while let Some(row) = rows.next()? {
        let id: i64 = row.get(0)?;
        let tag: Option<String> = row.get(3)?;
        let note = match notes.last_mut() {
            Some(note) if note.id == id => note,
            _ => {
                notes.push(Note {
                    id,
                    title: row.get(1)?,
                    body: row.get(2)?,
                    tags: Vec::new(),
                });
                notes.last_mut().expect("just pushed")
            }
        };
        note.tags.extend(tag);
    }
    Ok(notes)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db::notes::insert;
    use crate::db::test_util::{conn, temp_db};
    use crate::model::NoteInput;

    fn add(conn: &mut Connection, title: &str, body: &str, tags: &[&str]) -> Note {
        let input = NoteInput {
            title: title.into(),
            body: body.into(),
            tags: tags.iter().map(|&t| t.to_owned()).collect(),
        };
        insert(conn, input).unwrap()
    }

    fn ids(notes: &[Note]) -> Vec<i64> {
        notes.iter().map(|n| n.id).collect()
    }

    #[test]
    fn lists_all_with_tags_in_id_order() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        let a = add(&mut conn, "a", "", &["x", "y"]);
        let b = add(&mut conn, "b", "x", &[]);
        let c = add(&mut conn, "c", "", &["z"]);
        assert_eq!(list(&conn, &ListFilter::default()).unwrap(), [a, b, c]);
    }

    #[test]
    fn filters_combine() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        add(&mut conn, "Hello world", "", &["greet"]);
        add(&mut conn, "other", "say HELLO", &["greet", "misc"]);
        add(&mut conn, "nothing", "", &[]);
        add(&mut conn, "héllo", "100%_done", &["misc"]);

        let run = |filter: ListFilter| ids(&list(&conn, &filter).unwrap());
        let text = |t: &str| Some(t.to_owned());

        assert_eq!(
            run(ListFilter {
                tag: text("misc"),
                ..Default::default()
            }),
            [2, 4]
        );
        assert_eq!(
            run(ListFilter {
                tag: text("nope"),
                ..Default::default()
            }),
            [0; 0]
        );
        assert_eq!(
            run(ListFilter {
                text: text("hElLo"),
                ..Default::default()
            }),
            [1, 2]
        );
        assert_eq!(
            run(ListFilter {
                text: text("HÉLLO"),
                ..Default::default()
            }),
            [0; 0]
        );
        assert_eq!(
            run(ListFilter {
                text: text("%_"),
                ..Default::default()
            }),
            [4]
        );
        assert_eq!(
            run(ListFilter {
                text: text("_"),
                ..Default::default()
            }),
            [4]
        );
        assert_eq!(
            run(ListFilter {
                text: text(""),
                ..Default::default()
            }),
            [1, 2, 3, 4]
        );
        assert_eq!(
            run(ListFilter {
                tag: text("misc"),
                text: text("hello"),
                ..Default::default()
            }),
            [2]
        );
        assert_eq!(
            run(ListFilter {
                after: Some(2),
                ..Default::default()
            }),
            [3, 4]
        );
        assert_eq!(
            run(ListFilter {
                after: Some(-5),
                ..Default::default()
            }),
            [1, 2, 3, 4]
        );
        assert_eq!(
            run(ListFilter {
                limit: 2,
                ..Default::default()
            }),
            [1, 2]
        );
        assert_eq!(
            run(ListFilter {
                tag: text("greet"),
                after: Some(1),
                limit: 1,
                ..Default::default()
            }),
            [2]
        );
    }

    #[test]
    fn limit_counts_notes_not_tags() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        let a = add(&mut conn, "a", "", &["p", "q", "r"]);
        add(&mut conn, "b", "", &["p"]);
        let filter = ListFilter {
            limit: 1,
            ..Default::default()
        };
        assert_eq!(list(&conn, &filter).unwrap(), [a]);
    }
}

//! SQLite storage: a connection pool, the schema, and data access split by feature.
//!
//! Data-access functions are plain synchronous functions over a [`rusqlite::Connection`]; handlers
//! run them on the blocking thread pool with [`Db::run`]:
//!
//! ```ignore
//! let note = state.db.run(move |conn| db::notes::get(conn, id)).await?;
//! ```

pub mod crud;
pub mod list;
pub mod notes;
mod schema;
pub mod stats;

use std::path::Path;
use std::time::Duration;

use r2d2_sqlite::SqliteConnectionManager;
use rusqlite::Connection;

/// How long a connection waits for a lock held by another connection before failing.
const BUSY_TIMEOUT: Duration = Duration::from_secs(5);
const MAX_CONNECTIONS: u32 = 8;

#[derive(Debug, thiserror::Error)]
pub enum DbError {
    #[error("connection pool: {0}")]
    Pool(#[from] r2d2::Error),
    #[error("sqlite: {0}")]
    Sqlite(#[from] rusqlite::Error),
    #[error("database task failed: {0}")]
    Task(#[from] tokio::task::JoinError),
}

/// A handle to the database; cheap to clone.
#[derive(Clone)]
pub struct Db {
    pool: r2d2::Pool<SqliteConnectionManager>,
}

impl Db {
    /// Opens (creating if needed) the database file at `path` and brings its schema up to date.
    pub fn open(path: impl AsRef<Path>) -> Result<Self, DbError> {
        let path = path.as_ref();
        // Prepare the file on a single connection before the pool opens several at once: switching
        // to WAL needs an exclusive lock, and the setting persists in the database file.
        {
            let mut conn = Connection::open(path)?;
            configure(&mut conn)?;
            conn.pragma_update(None, "journal_mode", "WAL")?;
            schema::migrate(&mut conn)?;
        }
        let manager = SqliteConnectionManager::file(path).with_init(configure);
        let pool = r2d2::Pool::builder()
            .max_size(MAX_CONNECTIONS)
            .build(manager)?;
        Ok(Self { pool })
    }

    /// Runs `f` with a pooled connection on the blocking thread pool.
    ///
    /// Use [`rusqlite::TransactionBehavior::Immediate`] transactions for read-then-write work so that
    /// concurrent writers queue on the busy timeout instead of failing with `SQLITE_BUSY`.
    pub async fn run<F, T>(&self, f: F) -> Result<T, DbError>
    where
        F: FnOnce(&mut Connection) -> rusqlite::Result<T> + Send + 'static,
        T: Send + 'static,
    {
        let pool = self.pool.clone();
        tokio::task::spawn_blocking(move || {
            let mut conn = pool.get()?;
            Ok(f(&mut conn)?)
        })
        .await?
    }
}

fn configure(conn: &mut Connection) -> rusqlite::Result<()> {
    conn.busy_timeout(BUSY_TIMEOUT)?;
    // In WAL mode (set in `Db::open`), NORMAL sync is durable across application crashes.
    conn.pragma_update(None, "synchronous", "NORMAL")?;
    conn.pragma_update(None, "foreign_keys", true)?;
    Ok(())
}

#[cfg(test)]
pub(crate) mod test_util {
    use super::*;

    /// A database in a fresh temporary directory, deleted when the returned guard is dropped.
    pub fn temp_db() -> (Db, tempfile::TempDir) {
        let dir = tempfile::tempdir().expect("create temp dir");
        let db = Db::open(dir.path().join("notes.db")).expect("open database");
        (db, dir)
    }

    pub fn conn(db: &Db) -> r2d2::PooledConnection<SqliteConnectionManager> {
        db.pool.get().expect("get connection")
    }
}

//! Core data access: creating and reading notes, and the tag helpers shared by other features.

use rusqlite::{Connection, OptionalExtension, TransactionBehavior, params};

use crate::model::{Note, NoteInput};

/// Inserts a note and returns it with its new id.
pub fn insert(conn: &mut Connection, input: NoteInput) -> rusqlite::Result<Note> {
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    tx.execute(
        "INSERT INTO notes (title, body) VALUES (?1, ?2)",
        params![input.title, input.body],
    )?;
    let id = tx.last_insert_rowid();
    replace_tags(&tx, id, &input.tags)?;
    tx.commit()?;
    let NoteInput { title, body, tags } = input;
    Ok(Note {
        id,
        title,
        body,
        tags,
    })
}

/// The note with this id, if it exists.
pub fn get(conn: &Connection, id: i64) -> rusqlite::Result<Option<Note>> {
    let Some((title, body)) = conn
        .prepare_cached("SELECT title, body FROM notes WHERE id = ?1")?
        .query_row([id], |row| Ok((row.get(0)?, row.get(1)?)))
        .optional()?
    else {
        return Ok(None);
    };
    let tags = tags_of(conn, id)?;
    Ok(Some(Note {
        id,
        title,
        body,
        tags,
    }))
}

/// The tags of a note, sorted ascending.
pub fn tags_of(conn: &Connection, note_id: i64) -> rusqlite::Result<Vec<String>> {
    conn.prepare_cached("SELECT tag FROM note_tags WHERE note_id = ?1 ORDER BY tag")?
        .query_map([note_id], |row| row.get(0))?
        .collect()
}

/// Sets the tags of a note to exactly `tags`. Call inside a transaction.
pub fn replace_tags(conn: &Connection, note_id: i64, tags: &[String]) -> rusqlite::Result<()> {
    conn.prepare_cached("DELETE FROM note_tags WHERE note_id = ?1")?
        .execute([note_id])?;
    let mut insert = conn.prepare_cached("INSERT INTO note_tags (note_id, tag) VALUES (?1, ?2)")?;
    for tag in tags {
        insert.execute(params![note_id, tag])?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db::test_util::{conn, temp_db};

    fn input(title: &str, tags: &[&str]) -> NoteInput {
        NoteInput {
            title: title.into(),
            body: format!("{title} body"),
            tags: tags.iter().map(|&t| t.to_owned()).collect(),
        }
    }

    #[test]
    fn insert_then_get() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        let first = insert(&mut conn, input("a", &["x", "y"])).unwrap();
        let second = insert(&mut conn, input("b", &[])).unwrap();
        assert_eq!((first.id, second.id), (1, 2));
        assert_eq!(get(&conn, 1).unwrap(), Some(first));
        assert_eq!(get(&conn, 2).unwrap(), Some(second));
        assert_eq!(get(&conn, 3).unwrap(), None);
    }

    #[test]
    fn replace_tags_overwrites() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        let note = insert(&mut conn, input("a", &["x", "y"])).unwrap();
        replace_tags(&conn, note.id, &["z".to_owned()]).unwrap();
        assert_eq!(tags_of(&conn, note.id).unwrap(), ["z"]);
    }

    #[test]
    fn ids_are_not_reused() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        let note = insert(&mut conn, input("a", &["x"])).unwrap();
        conn.execute("DELETE FROM notes WHERE id = ?1", [note.id])
            .unwrap();
        assert_eq!(
            tags_of(&conn, note.id).unwrap(),
            Vec::<String>::new(),
            "tags cascade"
        );
        assert_eq!(insert(&mut conn, input("b", &[])).unwrap().id, 2);
    }
}

//! Schema creation and migrations, tracked with SQLite's `user_version`.

use rusqlite::{Connection, TransactionBehavior};

/// Migrations in order; migration `i` brings the schema from version `i` to `i + 1`.
const MIGRATIONS: &[&str] = &[
    // `AUTOINCREMENT` guarantees that ids are never reused, also after deleting the newest note.
    "CREATE TABLE notes (
         id    INTEGER PRIMARY KEY AUTOINCREMENT,
         title TEXT NOT NULL,
         body  TEXT NOT NULL DEFAULT ''
     );
     CREATE TABLE note_tags (
         note_id INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
         tag     TEXT NOT NULL,
         PRIMARY KEY (note_id, tag)
     ) WITHOUT ROWID;
     CREATE INDEX note_tags_by_tag ON note_tags (tag, note_id);",
];

pub fn migrate(conn: &mut Connection) -> rusqlite::Result<()> {
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let version: u32 = tx.pragma_query_value(None, "user_version", |row| row.get(0))?;
    let latest = u32::try_from(MIGRATIONS.len()).expect("migration count fits in u32");
    for migration in MIGRATIONS.iter().skip(version as usize) {
        tx.execute_batch(migration)?;
    }
    if version < latest {
        tx.pragma_update(None, "user_version", latest)?;
    }
    tx.commit()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn migrate_is_idempotent() {
        let mut conn = Connection::open_in_memory().unwrap();
        migrate(&mut conn).unwrap();
        migrate(&mut conn).unwrap();
        let version: u32 = conn
            .pragma_query_value(None, "user_version", |row| row.get(0))
            .unwrap();
        assert_eq!(version as usize, MIGRATIONS.len());
    }
}

//! Data access for `GET /stats` and `GET /tags`.
//!
//! Tag counts come from the `note_tags` table, which only holds tags
//! of existing notes.

use std::collections::BTreeMap;

use rusqlite::Connection;
use serde::Serialize;

/// The number of notes and, for each tag in use, the number of notes that have it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Stats {
    pub notes: i64,
    pub tags: BTreeMap<String, i64>,
}

/// A tag and the number of notes that have it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct TagCount {
    pub tag: String,
    pub count: i64,
}

/// The note count and per-tag counts, read from a single consistent snapshot.
pub fn stats(conn: &mut Connection) -> rusqlite::Result<Stats> {
    // A (deferred) read transaction, so that the note count and the tag counts agree even while
    // other connections write.
    let tx = conn.transaction()?;
    let notes = tx
        .prepare_cached("SELECT COUNT(*) FROM notes")?
        .query_row([], |row| row.get(0))?;
    let tags = tx
        .prepare_cached("SELECT tag, COUNT(*) FROM note_tags GROUP BY tag")?
        .query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?
        .collect::<rusqlite::Result<_>>()?;
    tx.commit()?;
    Ok(Stats { notes, tags })
}

/// Every tag in use with its note count, ordered by count descending, then tag ascending.
pub fn tag_counts(conn: &Connection) -> rusqlite::Result<Vec<TagCount>> {
    conn.prepare_cached(
        "SELECT tag, COUNT(*) AS count FROM note_tags GROUP BY tag ORDER BY count DESC, tag ASC",
    )?
    .query_map([], |row| {
        Ok(TagCount {
            tag: row.get(0)?,
            count: row.get(1)?,
        })
    })?
    .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db::notes::insert;
    use crate::db::test_util::{conn, temp_db};
    use crate::model::NoteInput;

    fn input(title: &str, tags: &[&str]) -> NoteInput {
        NoteInput {
            title: title.into(),
            body: String::new(),
            tags: tags.iter().map(|&t| t.to_owned()).collect(),
        }
    }

    fn tag_count(tag: &str, count: i64) -> TagCount {
        TagCount {
            tag: tag.into(),
            count,
        }
    }

    #[test]
    fn empty_database() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        assert_eq!(
            stats(&mut conn).unwrap(),
            Stats {
                notes: 0,
                tags: BTreeMap::new()
            }
        );
        assert_eq!(tag_counts(&conn).unwrap(), []);
    }

    #[test]
    fn counts_notes_per_tag() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        insert(&mut conn, input("a", &["b", "x"])).unwrap();
        insert(&mut conn, input("b", &["a", "x"])).unwrap();
        insert(&mut conn, input("c", &["c", "x"])).unwrap();
        insert(&mut conn, input("d", &["c"])).unwrap();
        insert(&mut conn, input("e", &[])).unwrap();

        let expected = BTreeMap::from([
            ("a".to_owned(), 1),
            ("b".to_owned(), 1),
            ("c".to_owned(), 2),
            ("x".to_owned(), 3),
        ]);
        assert_eq!(
            stats(&mut conn).unwrap(),
            Stats {
                notes: 5,
                tags: expected
            }
        );
        assert_eq!(
            tag_counts(&conn).unwrap(),
            [
                tag_count("x", 3),
                tag_count("c", 2),
                tag_count("a", 1),
                tag_count("b", 1)
            ]
        );
    }

    #[test]
    fn deleted_notes_no_longer_count() {
        let (db, _dir) = temp_db();
        let mut conn = conn(&db);
        let first = insert(&mut conn, input("a", &["x", "y"])).unwrap();
        insert(&mut conn, input("b", &["x"])).unwrap();
        conn.execute("DELETE FROM notes WHERE id = ?1", [first.id])
            .unwrap();

        assert_eq!(
            stats(&mut conn).unwrap(),
            Stats {
                notes: 1,
                tags: BTreeMap::from([("x".to_owned(), 1)])
            }
        );
        assert_eq!(tag_counts(&conn).unwrap(), [tag_count("x", 1)]);
    }
}

//! The error type returned by request handlers.

use axum::Json;
use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use serde_json::json;

use crate::db::DbError;
use crate::model::ValidationError;

/// An error answered as `{"error": "<message>"}` with the matching status code.
#[derive(Debug, thiserror::Error)]
pub enum ApiError {
    #[error("{0}")]
    BadRequest(String),
    #[error("not found")]
    NotFound,
    #[error("method not allowed")]
    MethodNotAllowed,
    #[error("payload too large")]
    PayloadTooLarge,
    #[error(transparent)]
    Database(#[from] DbError),
}

impl ApiError {
    pub fn bad_request(message: impl Into<String>) -> Self {
        Self::BadRequest(message.into())
    }

    pub fn status(&self) -> StatusCode {
        match self {
            Self::BadRequest(_) => StatusCode::BAD_REQUEST,
            Self::NotFound => StatusCode::NOT_FOUND,
            Self::MethodNotAllowed => StatusCode::METHOD_NOT_ALLOWED,
            Self::PayloadTooLarge => StatusCode::PAYLOAD_TOO_LARGE,
            Self::Database(_) => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }
}

impl From<ValidationError> for ApiError {
    fn from(err: ValidationError) -> Self {
        Self::BadRequest(err.to_string())
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let status = self.status();
        let message = if let Self::Database(err) = &self {
            // Do not leak internals to clients; keep the details in the log.
            tracing::error!("database error: {err}");
            "internal server error".to_owned()
        } else {
            self.to_string()
        };
        (status, Json(json!({ "error": message }))).into_response()
    }
}

/// Result type for request handlers.
pub type ApiResult<T> = Result<T, ApiError>;

//! Request extractors that answer malformed requests with the API's JSON errors.

use axum::body::Bytes;
use axum::extract::rejection::BytesRejection;
use axum::extract::{FromRequest, FromRequestParts, Path, Request};
use axum::http::StatusCode;
use axum::http::request::Parts;
use serde_json::Value;

use crate::error::ApiError;
use crate::model::NoteInput;

/// A request body parsed as JSON. Any syntax error is a 400.
///
/// The `Content-Type` header is not required.
#[derive(Debug)]
pub struct JsonBody(pub Value);

impl<S: Send + Sync> FromRequest<S> for JsonBody {
    type Rejection = ApiError;

    async fn from_request(req: Request, state: &S) -> Result<Self, Self::Rejection> {
        let bytes = Bytes::from_request(req, state)
            .await
            .map_err(body_rejection)?;
        serde_json::from_slice(&bytes)
            .map(JsonBody)
            .map_err(|err| ApiError::bad_request(format!("invalid JSON: {err}")))
    }
}

fn body_rejection(rejection: BytesRejection) -> ApiError {
    if rejection.status() == StatusCode::PAYLOAD_TOO_LARGE {
        ApiError::PayloadTooLarge
    } else {
        ApiError::bad_request(rejection.body_text())
    }
}

/// A validated note body (`{title, body?, tags?}`), see [`NoteInput::from_json`].
impl<S: Send + Sync> FromRequest<S> for NoteInput {
    type Rejection = ApiError;

    async fn from_request(req: Request, state: &S) -> Result<Self, Self::Rejection> {
        let JsonBody(value) = JsonBody::from_request(req, state).await?;
        Ok(NoteInput::from_json(value)?)
    }
}

/// The `{id}` path parameter of `/notes/{id}`.
///
/// Anything but a positive decimal integer is answered with 404, as no such note can exist.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct NoteId(pub i64);

impl NoteId {
    pub fn parse(segment: &str) -> Option<Self> {
        if segment.is_empty() || !segment.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        segment.parse().ok().filter(|&id| id > 0).map(NoteId)
    }
}

impl<S: Send + Sync> FromRequestParts<S> for NoteId {
    type Rejection = ApiError;

    async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
        let Path(segment) = Path::<String>::from_request_parts(parts, state)
            .await
            .map_err(|_| ApiError::NotFound)?;
        NoteId::parse(&segment).ok_or(ApiError::NotFound)
    }
}

