        .map(|i| {
            let app = app.clone();
            tokio::spawn(async move {
                app.create(json!({"title": format!("n{i}"), "tags": ["c"]}))
                    .await
            })
        })
        .collect();
    let mut ids = Vec::new();
    for task in tasks {
